export declare const dissolveGlsl = "// Noise-threshold dissolve. Returns x = keep (0/1), y = burn-edge amount [0,1].\nvec2 slu_dissolve(float noiseValue, float progress, float edgeWidth) {\n  float d = noiseValue - progress;\n  float keep = step(0.0, d);\n  float edge = 1.0 - smoothstep(0.0, max(edgeWidth, 0.0001), d);\n  return vec2(keep, edge * keep);\n}\n";
export declare const fresnelGlsl = "// Fresnel/rim term from a normal and a direction toward the viewer (same space).\nfloat slu_fresnel(vec3 n, vec3 toView, float power) {\n  return pow(1.0 - clamp(abs(dot(normalize(n), normalize(toView))), 0.0, 1.0), max(power, 0.0001));\n}\nfloat slu_rimBand(float fresnel, float width) { return smoothstep(1.0 - clamp(width, 0.001, 1.0), 1.0, fresnel); }\n";
export declare const iridescenceGlsl = "// Thin-film style iridescence mapped onto palette tokens instead of the physical spectrum.\nvec3 slu_thinFilm(float cosTheta, float thickness, vec3 a, vec3 b, vec3 c) {\n  float phase = thickness * (1.0 - cosTheta) * 6.2831853;\n  vec3 w = 0.5 + 0.5 * cos(phase + vec3(0.0, 2.094, 4.188));\n  return a * w.x + b * w.y + c * w.z;\n}\n";
export declare const noiseGlsl = "// Portable value noise + fbm. Pure functions, no engine uniforms.\nfloat slu_hash13(vec3 p) {\n  p = fract(p * 0.1031);\n  p += dot(p, p.zyx + 31.32);\n  return fract((p.x + p.y) * p.z);\n}\nfloat slu_hash11(float n) { return fract(sin(n) * 43758.5453123); }\nfloat slu_noise3(vec3 p) {\n  vec3 i = floor(p); vec3 f = fract(p);\n  vec3 u = f * f * (3.0 - 2.0 * f);\n  float n000 = slu_hash13(i), n100 = slu_hash13(i + vec3(1,0,0));\n  float n010 = slu_hash13(i + vec3(0,1,0)), n110 = slu_hash13(i + vec3(1,1,0));\n  float n001 = slu_hash13(i + vec3(0,0,1)), n101 = slu_hash13(i + vec3(1,0,1));\n  float n011 = slu_hash13(i + vec3(0,1,1)), n111 = slu_hash13(i + vec3(1,1,1));\n  return mix(mix(mix(n000, n100, u.x), mix(n010, n110, u.x), u.y),\n             mix(mix(n001, n101, u.x), mix(n011, n111, u.x), u.y), u.z);\n}\nfloat slu_fbm3(vec3 p) {\n  float a = 0.5, s = 0.0;\n  for (int i = 0; i < 4; i++) { s += a * slu_noise3(p); p = p * 2.03 + 17.1; a *= 0.5; }\n  return s / 0.9375;\n}\n";
export declare const paletteGlsl = "// Palette remapping: posterize + three-stop token gradient.\nfloat slu_luma(vec3 c) { return dot(c, vec3(0.2126, 0.7152, 0.0722)); }\nfloat slu_posterize(float x, float bands) { return bands < 1.5 ? x : floor(clamp(x, 0.0, 0.9999) * bands) / (bands - 1.0); }\nvec3 slu_ramp3(float t, vec3 lo, vec3 mid, vec3 hi) {\n  t = clamp(t, 0.0, 1.0);\n  return t < 0.5 ? mix(lo, mid, t * 2.0) : mix(mid, hi, t * 2.0 - 1.0);\n}\n";
export declare const toonGlsl = "// Banded diffuse ramp with soft step edges. x in [0,1].\nfloat slu_toonBand(float x, float steps, float soft) {\n  x = clamp(x, 0.0, 1.0);\n  if (steps < 1.5) return x;\n  float s = x * steps;\n  float base = floor(s);\n  float f = s - base;\n  float edge = smoothstep(0.5 - soft * 0.5, 0.5 + soft * 0.5 + 0.0001, f);\n  return clamp((base + edge) / steps, 0.0, 1.0);\n}\nfloat slu_wrapLight(float ndl, float wrap) { return clamp((ndl + wrap) / (1.0 + wrap), 0.0, 1.0); }\n";
